type Coordinate = [number,number];
type ReplayEvent = 'normal'|'heat_excursion'|'road_delay'|'recovery';
interface Sensor {
  device_id:string; source:'simulated_replay'|'gateway_reported'; observed_at:string; retrieved_at:string;
  temperature_c:number|null; ambient_temperature_c:number|null; humidity_percent:number|null;
  vibration_g:number|null; ethylene_ppm:number|null; temperature_basis:string; calibration_status:string;
}
interface Context {
  network_revision:number; simulation:true; demo_shipment_id?:string;
  shipments:{id:string;freshness_session_id?:string|null;origin_name:string;destination_name:string;lot_id:string;truck_id:string}[];
  sessions:{id:string;version:number;shipment_id:string;created_at:string}[];
  gateway:{configured:boolean;endpoint:string;notice:string};limitations:string[];
}
interface RescueOption {
  destination_id:string;destination_name:string;kind:string;eligible:boolean;dispatchable:boolean;
  duration_hours:number;distance_km:number;quality_margin_hours:number|null;fallback:boolean;provenance:string;
  geometry:{type:'LineString';coordinates:Coordinate[]};exclusion_reasons:string[];
}
interface Pick {lot_id:string;warehouse_id:string;destination_id:string;quantity_kg:number;remaining_at_arrival_hours:number;rank:number}
